javascript:(function(){const D=3000;const INC=['pluginfile.php','mod/resource/view.php','/files/','/download'];const EXC=['/mod/quiz/','/mod/forum/','/mod/assign/','/mod/chat/','/mod/choice/','/mod/feedback/'];const EXT=/\.(pdf|docx?|pptx?|xlsx?|odt|ods|odp|zip|csv|txt)(\?|$)/i;const SEL='.activityname,.instancename,li.activity,.ig-title,.course-content li';const links=[...new Map([...document.querySelectorAll('a[href]')].filter(a=>{const h=a.href;return a.closest(SEL)&&(INC.some(p=>h.includes(p))||EXT.test(h))&&!EXC.some(p=>h.includes(p));}).map(a=>[a.href,a])).values()];if(!links.length){alert('No downloadable files found on this page.\n\nMake sure you are on the course main page, not inside an individual activity.');return;}if(!confirm('Found '+links.length+' file(s).\n\nDownload all with a '+D/1000+'s delay between each?'))return;links.forEach((l,i)=>setTimeout(()=>{const a=document.createElement('a');a.href=l.href;a.target='_blank';a.style.display='none';document.body.appendChild(a);a.click();document.body.removeChild(a);},i*D));})();
